import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> {'side':..., 'price':..., 'qty':..., 'seq':..., 'active':bool}
    seq_counter = 0

    def push_order(side, oid, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return o, oid
        return None, None

    def match_incoming(side, price, qty, is_market):
        # price is None if market order (any price)
        remaining = qty
        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            o, oid = top_valid(opp_heap)
            if o is None:
                break
            resting_price = o['price']
            if not is_market:
                if side == 'buy':
                    if resting_price > price:
                        break
                else:
                    if resting_price < price:
                        break
            trade_qty = min(remaining, o['qty'])
            if side == 'buy':
                trades.append([None, oid, resting_price, trade_qty])  # placeholder, fill buy_id later
            else:
                trades.append([oid, None, resting_price, trade_qty])
            o['qty'] -= trade_qty
            remaining -= trade_qty
            if o['qty'] <= 0:
                o['active'] = False
                # will be popped lazily next time
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, is_market=False)
            # fix trades that involve this incoming order
            if side == 'buy':
                for t in trades:
                    if t[0] is None:
                        t[0] = oid
            else:
                for t in trades:
                    if t[1] is None:
                        t[1] = oid
            if remaining > 0:
                push_order(side, oid, price, remaining, seq)

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, is_market=False)
            if side == 'buy':
                for t in trades:
                    if t[0] is None:
                        t[0] = oid
            else:
                for t in trades:
                    if t[1] is None:
                        t[1] = oid
            # discard remainder

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, is_market=True)
            if side == 'buy':
                for t in trades:
                    if t[0] is None:
                        t[0] = oid
            else:
                for t in trades:
                    if t[1] is None:
                        t[1] = oid
            # discard remainder

    return trades

